"""Specs for every real-world task generated by ``tools/make_real_task.py``.

Each spec is a self-contained dict.

The four hand-authored real-world tasks (lucene_pointtree_eager_001,
rxjava_reduce_scan_001, netty_pool_cache_size_001,
guava_immutableset_copyof_001) are NOT regenerated by this script — they
were authored before this file existed and live as-is on disk.
"""

from __future__ import annotations

from typing import Any

JMH_HEADER = """package bench;

import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
"""


SPECS: list[dict[str, Any]] = []


def _add(
    *,
    id_: str,
    target_class: str,
    expected_input_shapes: list[str],
    tags: list[str],
    provenance: dict[str, str],
    sut: str,
    regressed: str,
    regression_id: str,
    regression_description: str,
    test_class: str,
    test_source: str,
    benchmark_class: str,
    benchmark_source: str,
) -> None:
    cls = target_class.split(".")[-1]
    SPECS.append(
        {
            "id": id_,
            "target_class": target_class,
            "expected_input_shapes": expected_input_shapes,
            "tags": tags + ["real-world"],
            "provenance": provenance,
            "sut_files": {f"bench/{cls}.java": sut},
            "regressed_files": {f"bench/{cls}.java": regressed},
            "regression_id": regression_id,
            "regression_description": regression_description,
            "test_class": test_class,
            "test_source": test_source,
            "benchmark_class": benchmark_class,
            "benchmark_source": benchmark_source,
        }
    )


