_add(
    id_="flink_string_value_writeutf_001",
    target_class="bench.StringEncoder",
    expected_input_shapes=["String of length 128, mostly ASCII"],
    tags=["string", "flink"],
    provenance={
        "project": "apache/flink",
        "url": "https://github.com/apache/flink/pull/10358",
        "commit": "be967fa1f71bfefe37db3c4a7e0e8a954b30df8c",
        "description": (
            "Inspired by Flink PR #10358 ([FLINK-14346] faster implementation\n"
            "of StringValue writeString and readString). The simplified SUT\n"
            "here encodes a String to UTF-8 bytes with a pre-sized buffer;\n"
            "the full real class is not extracted, so the SUT may be\n"
            "expanded later by following the linked PR."
        ),
    },
    sut="""package bench;

public final class StringEncoder {

    private StringEncoder() {}

    public static byte[] encode(String s) {
        int n = s.length();
        byte[] out = new byte[n * 3];
        int p = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c < 0x80) {
                out[p++] = (byte) c;
            } else if (c < 0x800) {
                out[p++] = (byte) (0xC0 | (c >> 6));
                out[p++] = (byte) (0x80 | (c & 0x3F));
            } else {
                out[p++] = (byte) (0xE0 | (c >> 12));
                out[p++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                out[p++] = (byte) (0x80 | (c & 0x3F));
            }
        }
        byte[] result = new byte[p];
        System.arraycopy(out, 0, result, 0, p);
        return result;
    }
}
""",
    regressed="""package bench;

import java.util.Arrays;

public final class StringEncoder {

    private StringEncoder() {}

    // Regressed: grow the output buffer one byte at a time via copyOf.
    public static byte[] encode(String s) {
        int n = s.length();
        byte[] out = new byte[0];
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c < 0x80) {
                out = Arrays.copyOf(out, out.length + 1);
                out[out.length - 1] = (byte) c;
            } else if (c < 0x800) {
                out = Arrays.copyOf(out, out.length + 2);
                out[out.length - 2] = (byte) (0xC0 | (c >> 6));
                out[out.length - 1] = (byte) (0x80 | (c & 0x3F));
            } else {
                out = Arrays.copyOf(out, out.length + 3);
                out[out.length - 3] = (byte) (0xE0 | (c >> 12));
                out[out.length - 2] = (byte) (0x80 | ((c >> 6) & 0x3F));
                out[out.length - 1] = (byte) (0x80 | (c & 0x3F));
            }
        }
        return out;
    }
}
""",
    regression_id="per_char_buffer_grow",
    regression_description="Grow the output buffer one byte at a time via Arrays.copyOf.",
    test_class="StringEncoderTest",
    test_source="""package bench;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class StringEncoderTest {
    @Test public void asciiRoundTrip() {
        assertArrayEquals(new byte[]{'a','b','c'}, StringEncoder.encode("abc"));
    }
    @Test public void emptyString() {
        assertEquals(0, StringEncoder.encode("").length);
    }
    @Test public void twoByteSequence() {
        byte[] b = StringEncoder.encode("\u00A9");
        assertArrayEquals(new byte[]{(byte)0xC2, (byte)0xA9}, b);
    }
    @Test public void threeByteSequence() {
        byte[] b = StringEncoder.encode("\u20AC");
        assertArrayEquals(new byte[]{(byte)0xE2, (byte)0x82, (byte)0xAC}, b);
    }
}
""",
    benchmark_class="StringEncoderBenchmark",
    benchmark_source=JMH_HEADER + """import org.openjdk.jmh.infra.Blackhole;

@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
public class StringEncoderBenchmark {

    @Param({"128"})
    public int length;

    private String input;

    @Setup
    public void setup() {
        StringBuilder sb = new StringBuilder(length);
        for (int i = 0; i < length; i++) sb.append((char) ('a' + (i % 26)));
        input = sb.toString();
    }

    @Benchmark
    public void encode(Blackhole bh) {
        bh.consume(StringEncoder.encode(input));
    }
}
""",
)


