_add(
    id_="flink_unaligned_checkpoint_recover_001",
    target_class="bench.BufferAssembler",
    expected_input_shapes=["64 byte[] slices, each 256 bytes long"],
    tags=["bytes", "flink"],
    provenance={
        "project": "apache/flink",
        "url": "https://github.com/apache/flink/pull/11687",
        "commit": "d7525baf093035c9b0fe125602814833388d1973",
        "description": (
            "Inspired by Flink PR #11687 ([FLINK-16536] InputChannel state\n"
            "recovery for unaligned checkpoints). The simplified SUT here\n"
            "concatenates byte slices into a single output buffer; the full\n"
            "real class is not extracted, so the SUT may be expanded later\n"
            "by following the linked PR."
        ),
    },
    sut="""package bench;

public final class BufferAssembler {

    private BufferAssembler() {}

    public static byte[] assemble(byte[][] slices) {
        int total = 0;
        for (int i = 0; i < slices.length; i++) total += slices[i].length;
        byte[] out = new byte[total];
        int p = 0;
        for (int i = 0; i < slices.length; i++) {
            byte[] s = slices[i];
            System.arraycopy(s, 0, out, p, s.length);
            p += s.length;
        }
        return out;
    }
}
""",
    regressed="""package bench;

import java.io.ByteArrayOutputStream;

public final class BufferAssembler {

    private BufferAssembler() {}

    // Regressed: route through an intermediate ByteArrayOutputStream and
    // clone the result one more time before returning it.
    public static byte[] assemble(byte[][] slices) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        for (int i = 0; i < slices.length; i++) {
            byte[] s = slices[i];
            bos.write(s, 0, s.length);
        }
        byte[] tmp = bos.toByteArray();
        return tmp.clone();
    }
}
""",
    regression_id="intermediate_alloc",
    regression_description="Buffer through ByteArrayOutputStream and clone the result.",
    test_class="BufferAssemblerTest",
    test_source="""package bench;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class BufferAssemblerTest {
    @Test public void joinsTwoSlices() {
        byte[] out = BufferAssembler.assemble(new byte[][]{{1,2}, {3,4,5}});
        assertArrayEquals(new byte[]{1,2,3,4,5}, out);
    }
    @Test public void emptyInput() {
        assertEquals(0, BufferAssembler.assemble(new byte[0][]).length);
    }
    @Test public void preservesOrder() {
        byte[] out = BufferAssembler.assemble(new byte[][]{{9}, {8}, {7}});
        assertArrayEquals(new byte[]{9,8,7}, out);
    }
    @Test public void skipsEmptySlices() {
        byte[] out = BufferAssembler.assemble(new byte[][]{{}, {1}, {}, {2}});
        assertArrayEquals(new byte[]{1,2}, out);
    }
}
""",
    benchmark_class="BufferAssemblerBenchmark",
    benchmark_source=JMH_HEADER + """import org.openjdk.jmh.infra.Blackhole;

@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
public class BufferAssemblerBenchmark {

    @Param({"64"})
    public int slices;

    @Param({"256"})
    public int sliceSize;

    private byte[][] input;

    @Setup
    public void setup() {
        input = new byte[slices][sliceSize];
        for (int i = 0; i < slices; i++)
            for (int j = 0; j < sliceSize; j++)
                input[i][j] = (byte) ((i * 31 + j) & 0xff);
    }

    @Benchmark
    public void assemble(Blackhole bh) {
        bh.consume(BufferAssembler.assemble(input));
    }
}
""",
)


