_add(
    id_="cassandra_token_lookup_001",
    target_class="bench.TokenLookup",
    expected_input_shapes=["sorted long[] of length 4096; 256 random targets per call"],
    tags=["search", "cassandra"],
    provenance={
        "project": "apache/cassandra",
        "url": "https://github.com/apache/cassandra",
        "description": (
            "Inspired by general Apache Cassandra token-ring lookup\n"
            "patterns (no single PR cited): hot paths binary-search the\n"
            "sorted token array instead of linear-scanning. The\n"
            "simplified SUT here mirrors that index lookup; the full real\n"
            "class is not extracted."
        ),
    },
    sut="""package bench;

public final class TokenLookup {

    private TokenLookup() {}

    public static int find(long[] tokens, long target) {
        int lo = 0, hi = tokens.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (tokens[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}
""",
    regressed="""package bench;

public final class TokenLookup {

    private TokenLookup() {}

    // Regressed: linear scan through the sorted token array.
    public static int find(long[] tokens, long target) {
        int i = 0;
        while (i < tokens.length && tokens[i] < target) {
            i++;
        }
        return i;
    }
}
""",
    regression_id="linear_scan",
    regression_description="Linear scan instead of binary search.",
    test_class="TokenLookupTest",
    test_source="""package bench;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class TokenLookupTest {
    @Test public void exactMatch() {
        assertEquals(2, TokenLookup.find(new long[]{1L, 3L, 5L, 7L}, 5L));
    }
    @Test public void beyondEnd() {
        assertEquals(4, TokenLookup.find(new long[]{1L, 3L, 5L, 7L}, 100L));
    }
    @Test public void betweenValues() {
        assertEquals(3, TokenLookup.find(new long[]{1L, 3L, 5L, 7L}, 6L));
    }
    @Test public void beforeStart() {
        assertEquals(0, TokenLookup.find(new long[]{10L}, 1L));
    }
    @Test public void emptyArray() {
        assertEquals(0, TokenLookup.find(new long[0], 0L));
    }
}
""",
    benchmark_class="TokenLookupBenchmark",
    benchmark_source=JMH_HEADER + """import java.util.Random;
import org.openjdk.jmh.infra.Blackhole;

@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
public class TokenLookupBenchmark {

    @Param({"4096"})
    public int size;

    @Param({"256"})
    public int queries;

    private long[] tokens;
    private long[] targets;

    @Setup
    public void setup() {
        Random rng = new Random(42L);
        tokens = new long[size];
        long v = 0;
        for (int i = 0; i < size; i++) {
            v += 1 + rng.nextInt(8);
            tokens[i] = v;
        }
        targets = new long[queries];
        for (int i = 0; i < queries; i++) targets[i] = rng.nextInt((int) v + 16);
    }

    @Benchmark
    public void find(Blackhole bh) {
        for (int i = 0; i < queries; i++) bh.consume(TokenLookup.find(tokens, targets[i]));
    }
}
""",
)


